mapper.select:
SELECT c.id, c.blog_id, c.user_id, c.parent_id, c.reply_user_id, c.content, c.status, c.like_count, c.create_time, c.update_time, c.deleted FROM tb_comment c LEFT JOIN tb_user u ON c.user_id = u.id WHERE c.deleted = 0
AND c.blog_id = #{blogId}
AND c.status = #{status}
AND ( c.content LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY c.create_time DESC
